CREATE COLUMN TABLE "TEST_AP"."OPCT" ("DocEntry" INTEGER CS_INT NOT NULL , "TmplCode" NVARCHAR(15) NOT NULL , "TmplName" NVARCHAR(100), "XMLFile" BLOB MEMORY THRESHOLD 1000, PRIMARY KEY ("DocEntry")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OPCT_TMPLCODE" ON "TEST_AP"."OPCT" ( "TmplCode" ASC )